def svg(kind):
    return f'<svg viewBox="0 0 24 24" aria-hidden="true">{SVG[kind]}</svg>'

def nav(active):
    links = [('home','الرئيسية','/'),('employees','الموظفون','/employees'),('moves','الحركات','/movements')]
    rendered = ''.join(f'<a href="{href}" class="{"active" if href==active else ""}">{svg(kind)}<span>{label}</span></a>' for kind,label,href in links)
    rendered += f'<a href="/reports-missions" class="{"active" if active=="/reports-missions" else ""}">{svg("reports")}<span>التقارير والمأموريات</span></a>'
    rendered += f'<a href="/structure" class="{"active" if active=="/structure" else ""}">{svg("admin")}<span>الإدارة</span></a>'
    return f'''<aside class="ui-sidebar premium-sidebar" id="appSidebar"><div class="ui-brand premium-brand"><div class="ui-brand-mark">{svg('admin')}</div><div class="ui-brand-copy"><strong>حركات الموظفين</strong><span>المركزية</span></div><button class="ui-collapse" aria-label="تصغير القائمة">‹</button></div><div class="premium-side-user"><div class="ui-avatar">أ</div><div><b>أحمد هشام</b><small>Admin</small></div></div><div class="premium-nav-label">مساحة العمل</div><nav class="ui-nav premium-nav">{rendered}</nav><div class="ui-spacer"></div><div class="premium-side-footer"><a>{svg('employees')}<span>حسابي</span></a><a>{svg('reports')}<span>خروج</span></a></div><div class="ui-version">الإصدار 68.47.1</div></aside>'''

