report=[]
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True, executable_path='/usr/bin/chromium', args=['--no-sandbox'])
    for key,(path,page,title,content,active) in pages.items():
        styles=styles_for['mission' if key=='mission-from-ticket' else key]
        html=shell(path,page,title,content,active,styles)
        (OUT/f'{key}.html').write_text(html,encoding='utf-8')
        for mode,width,height,open_sidebar in [('desktop',1440,1000,False),('mobile',390,844,False),('narrow',360,800,False),('mobile-sidebar-open',390,844,True)]:
            pg=browser.new_page(viewport={'width':width,'height':height},device_scale_factor=1)
            errors=[]
            pg.on('pageerror', lambda exc, e=errors: e.append(str(exc)))
            pg.on('console', lambda msg,e=errors: e.append(msg.text) if msg.type=='error' else None)
            pg.set_content(html,wait_until='load')
            if open_sidebar:
                pg.evaluate("document.querySelector('.premium-sidebar')?.classList.add('is-open')")
            pg.screenshot(path=str(OUT/f'{key}-{mode}.png'),full_page=True)
            m=pg.evaluate('''() => {const s=document.querySelector('.premium-sidebar');return {docWidth:document.documentElement.scrollWidth,viewWidth:document.documentElement.clientWidth,bodyWidth:document.body.scrollWidth,sidebarBg:getComputedStyle(s).backgroundColor,sidebarImage:getComputedStyle(s).backgroundImage,mainWidth:document.querySelector('.ui-main')?.getBoundingClientRect().width,contentWidth:document.querySelector('.ui-page,.catalog-workspace,.smart-employees-page')?.getBoundingClientRect().width,styleSheets:document.querySelectorAll('style[data-source]').length}}''')
            report.append({'page':key,'mode':mode,'viewport':[width,height],**m,'sidebarOpen':open_sidebar,'errors':errors})
            pg.close()
    browser.close()
(OUT/'render-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
summary={'previews':len(report),'errors':sum(len(x['errors']) for x in report),'overflow':sum(1 for x in report if x['docWidth']>x['viewWidth'] or x['bodyWidth']>x['viewWidth']),'pages':list(pages)}
(OUT/'preview-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(summary,ensure_ascii=False,indent=2))
